------------ import ------------
local CoWait = CS.Engine.Lib.CoWait
------------ import ------------
---@type CardProgressionConstants
local CardProgressionConstants = import("Game.CardProgression.CardProgressionConstants")
local MaxAttrNum = 3
local cardComp  = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
local CardProgressionUtils     = import("Game.CardProgression.CardProgressionUtils")
local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")
---@type CardProgressionSkillUtils
local CardProgressionSkillUtils = import("Game.CardProgression.CardProgressionSkillUtils")

---@class UIFightChooseCardsFetterNode
---@field Env                           	UIFightChooseCardsFetterNode
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field TxtInfo3                      	UnityEngine.RectTransform               
---@field TxtInfo2                      	UnityEngine.RectTransform               
---@field TxtName                       	UnityEngine.RectTransform               
---@field AttributeGroup3               	UnityEngine.RectTransform               
---@field AttributeGroup2               	UnityEngine.RectTransform               
---@field AttributeGroup1               	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform                
local UIFightChooseCardsFetterNode = Class("UIFightChooseCardsFetterNode")

function UIFightChooseCardsFetterNode:__init()
    self._targetCardId = 0             --主卡牌id
    self._cardData = nil               --
end

function UIFightChooseCardsFetterNode:__delete()
    self._targetCardId = 0             --主卡牌id
    self._cardData = nil             --
end

function UIFightChooseCardsFetterNode:Awake()
    SetButtonAction(self.BtnExplain, Bind(self, self.OnBtnTips))
end

function UIFightChooseCardsFetterNode:OnBtnTips()
    local desc = localize("1.角色升星会提升加成效果\n2.角色之间形成特殊羁绊时，会额外获得特殊效果")
    GameUtils.ShowFightChooseCardsFetterTipsNode(self.BtnExplain, localize("羁绊效果"), desc)
end

function UIFightChooseCardsFetterNode:RefreshInfo(targetCardId, cardData)
    self._cardData = cardData
    local isInit = self._targetCardId == 0
    self._targetCardId = checkNumber(targetCardId)
    if self._targetCardId <= 0 then
        return
    end

    if isInit then
        self:FillTargetCard() 
    end

    CfUtils.SetActive(self.HeadGroup, cardData ~= nil)
    if cardData then
        self:FillSelf()
    end
end

function UIFightChooseCardsFetterNode:FillTargetCard()
    local dojo = cardComp:GetCardById(cardComp:GetIdByCardId(self._targetCardId))
    CfUtils.RefeshCommonSmallHeroGo(self.CommonSmallHeadNode, dojo)
    CfUtils.SetActive(self.HeadGroup, false)

    CfUtils.SetUISwitchImage(self.ImgSymbol1, 1)
    CfUtils.SetUISwitchImage(self.ImgSymbol2, 1)
    CfUtils.SetUISwitchImage(self.ImgSymbol3, 1)
    
    local t = {}
    local entity = CardProgressionUtils.GenerateEntityByCardDojo(dojo)
    FormulaUtils.CalcCardCombatEffectiveness(entity, nil, function (vo, num, index)
        local order = vo.order
        if vo.order > 0 then
            local attribute_format = attribute_format
            local text = attribute_format(vo.isConversion, num)
            --只要前三个
            if checkNumber(vo.id) >= 1 and checkNumber(vo.id) <= 3 then
                table.insert(t, {
                    order = order,
                    icon = vo.icon,
                    name = vo.name,
                    attrNum = num,
                    finalNum = text,
                    viewType = CardProgressionConstants.AttrNodeType.Single,
                })
            end
        end
    end)

    --cardComp:GetCardById(self._cardData.id) 
    for i = 1, MaxAttrNum do
        local go = self["AttributeGroup"..i]
        if go then
            local data = t[i]
            CfUtils.FillText(go.transform:Find("Layout/TxtNumNormal"), data.finalNum)
            CfUtils.SetActive(go.transform:Find("Layout/TxtNumPlus"), false)
        end
    end

    CfUtils.SetActive(self.BaseEffect, false)
    CfUtils.SetActive(self.SpecialEffect, false)
end

function UIFightChooseCardsFetterNode:FillSelf()
    CfUtils.SetActive(self.HeadGroup, true)
    local vo = CardConfMgr:GetInstance():GetCardByRefId(self._cardData.cardId)
    CfUtils.SetUISwitchImage(self.ImgQuality, vo.rare)

    local skinId = vo.defaultSkin
    if self._cardData and isSet(self._cardData, "cardSkin") then
        skinId = checkNumber(self._cardData.cardSkin)
    end
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
    CfUtils.FillImage(self.ImgCardHead, skinVo.buffHead)

    local fettersId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(self._targetCardId, self._cardData.cardId)
    local isActiveFetters = fettersId > 0
    CfUtils.SetActive(self.ImgIcon, isActiveFetters)
    CfUtils.SetActive(self.TxtInfo3, isActiveFetters)
    CfUtils.SetActive(self.TxtName, isActiveFetters)

    CfUtils.SetActive(self.SpecialEffect, isActiveFetters)
    CfUtils.SetActive(self.UIFX_FetterAnimGlow, isActiveFetters)
    if isActiveFetters then
        local vo = CardConfMgr:GetInstance():GetRoleCardSynergiesVo(fettersId)
        if vo then
            CfUtils.FillText(self.TxtName, vo.relationName)
            local name, desc = CardProgressionSkillUtils.ParseSkillBuffDesc(vo.buff)
            CfUtils.FillText(self.TextDesc2, desc)
        end 
    end
    
    CfUtils.SetUISwitchImage(self.ImgSymbol1, 2)
    CfUtils.SetUISwitchImage(self.ImgSymbol2, 2)
    CfUtils.SetUISwitchImage(self.ImgSymbol3, 2)

    local t = {}
    local addNum = CardConfMgr:GetInstance():GetSynergiesAddNum(self._cardData)

    local entity = CardProgressionUtils.GenerateEntityByCardDojo(self._cardData)
    FormulaUtils.CalcCardCombatEffectiveness(entity, nil, function (vo, num, index)
        local _num = 0
        if isActiveFetters then
            local fettersVo = CardConfMgr:GetInstance():GetRoleCardSynergiesVo(fettersId)
            local t = CfUtils.Split(fettersVo.property)
            local basicAttrAdditionVo = CardConfMgr:GetInstance():GetBasicAttrAdditionById(t[1])
            if checkNumber(basicAttrAdditionVo.attrId) == checkNumber(vo.id) then
                _num = checkNumber(t[2])
            end
        end

        local order = vo.order
        if vo.order > 0 then
            local attribute_format = attribute_format
            local text = attribute_format(vo.isConversion, num * checkNumber(addNum) + _num)
            --只要前三个
            if checkNumber(vo.id) >= 1 and checkNumber(vo.id) <= 3 then
                table.insert(t, {
                    order = order,
                    icon = vo.icon,
                    name = vo.name,
                    attrNum = num,
                    finalNum = text,
                    viewType = CardProgressionConstants.AttrNodeType.Single,
                })
            end
        end
    end)
    
    --cardComp:GetCardById(self._cardData.id) 
    for i = 1, MaxAttrNum do
        local go = self["AttributeGroup"..i]
        if go then
            local data = t[i]
            CfUtils.SetActive(go.transform:Find("Layout/TxtNumPlus"), true)
            CfUtils.FillText(go.transform:Find("Layout/TxtNumPlus"), "+"..data.finalNum)
        end
    end
    
    CfUtils.SetActive(self.BaseEffect, true)
    CfUtils.FillText(self.TxtInfo2, localize("提供<color=#00FFF6>_name_</color>自身基础属性<color=#00FFF6>_num_%</color>加成", {_name_ = skinVo.name, _num_ = string.format('%g', checkInt(addNum * 10000) / 100)}))
end

function UIFightChooseCardsFetterNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightChooseCardsFetterNode





